import * as T from './vendor/three.module.js';
import {createPlayerHand} from './player-hand.js';
export function createRobotGreeting({robot,camera,stopSpeech=()=>{}}){
 const start=robot.position.clone(),rotation=robot.quaternion.clone(),cameraRotation=camera.quaternion.clone(),hand=createPlayerHand(T,camera);hand.g.scale.setScalar(.8);
 // Replace the old rigid right arm with shoulder, elbow, wrist and fingers.
 for(const part of [...robot.children])if(part.isMesh&&part.position.x>=-.45&&part.position.x<=-.35&&part.position.y>=.47&&part.position.y<=1.5){robot.remove(part);part.geometry?.dispose();part.material?.dispose();}
 const arm=new T.Group();arm.name='Robot articulated handshake arm';robot.add(arm);const metal=new T.MeshStandardMaterial({color:0x899d98,metalness:.65,roughness:.32}),dark=new T.MeshStandardMaterial({color:0x354d50,metalness:.5,roughness:.45});
 const upper=new T.Mesh(new T.CylinderGeometry(.065,.07,1,14),metal),forearm=new T.Mesh(new T.CylinderGeometry(.06,.065,1,14),metal),elbow=new T.Mesh(new T.SphereGeometry(.085,16,12),dark),palm=new T.Group();palm.name='Robot offered palm';arm.add(upper,forearm,elbow,palm);const block=new T.Mesh(new T.BoxGeometry(.15,.065,.14),metal);palm.add(block);const digits=[];for(let i=0;i<4;i++){const joint=new T.Group();joint.position.set((i-1.5)*.035,0,.065);palm.add(joint);const proximal=new T.Mesh(new T.CapsuleGeometry(.014,.045,4,8),metal);proximal.rotation.x=Math.PI/2;proximal.position.z=.025;joint.add(proximal);const tip=new T.Group();tip.position.z=.055;joint.add(tip);const distal=new T.Mesh(new T.CapsuleGeometry(.013,.025,4,8),dark);distal.rotation.x=Math.PI/2;distal.position.z=.02;tip.add(distal);digits.push({joint,tip});}const thumb=new T.Group();thumb.position.set(-.08,0,0);palm.add(thumb);const thumbPad=new T.Mesh(new T.CapsuleGeometry(.02,.055,4,8),metal);thumbPad.rotation.x=Math.PI/2;thumbPad.position.z=.025;thumb.add(thumbPad);
 function closeFingers(u){for(const [i,f]of digits.entries()){f.joint.rotation.x=u*(.7+i*.035);f.tip.rotation.x=u*1.15;}thumb.rotation.y=-.5+u*.6;thumb.rotation.x=u*.65;palm.userData.grip=u;}

 const legs=robot.children.filter(o=>o.isMesh&&Math.abs(Math.abs(o.position.x)-.18)<.001&&Math.abs(o.position.y-.4)<.001);let time=0,state='waiting',from=camera.position.clone(),contact=new T.Vector3();const up=new T.Vector3(0,1,0),shoulder=new T.Vector3(-.4,1.45,0),restElbow=new T.Vector3(-.4,1.02,0),restWrist=new T.Vector3(-.4,.63,0);
 const ease=u=>{u=T.MathUtils.clamp(u,0,1);return u*u*(3-2*u);};
 function bone(mesh,a,b){mesh.position.copy(a).add(b).multiplyScalar(.5);mesh.scale.y=a.distanceTo(b);mesh.quaternion.setFromUnitVectors(up,b.clone().sub(a).normalize());}
 function armPose(amount,bob=0){robot.updateMatrixWorld(true);const wrist=restWrist.clone().lerp(robot.worldToLocal(contact.clone()),amount),joint=restElbow.clone().lerp(new T.Vector3(-.48,1.16,.28),amount);joint.y+=bob*.5;bone(upper,shoulder,joint);bone(forearm,joint,wrist);elbow.position.copy(joint);palm.position.copy(wrist);palm.rotation.set(0,0,-amount*Math.PI/2);}
 function finish(){state='done';robot.position.copy(start);robot.quaternion.copy(rotation);legs.forEach(l=>l.rotation.x=0);hand.reset();camera.quaternion.copy(cameraRotation);armPose(0);closeFingers(0);}
 function begin(){if(state!=='waiting')return;state='approaching';time=0;from.copy(camera.position);cameraRotation.copy(camera.quaternion);}
 function update(dt){if(state==='waiting'||state==='done')return false;time+=dt;const approach=ease(time/.85);camera.position.copy(from).lerp(new T.Vector3(start.x,1.65,start.z+1.25),approach);robot.position.copy(start);robot.lookAt(camera.position.x,robot.position.y,camera.position.z);camera.lookAt(robot.position.x,1.4,robot.position.z);const reach=ease((time-1)/.5)*(1-ease((time-2.8)/.4)),bob=time>1.5&&time<2.8?Math.sin((time-1.5)/1.3*Math.PI*4)*Math.sin((time-1.5)/1.3*Math.PI)*.025:0;contact.set(start.x-.18,1.35+bob,start.z+.65);armPose(reach,bob);const squeeze=ease((time-1.5)/.18)*(1-ease((time-2.6)/.2));closeFingers(squeeze);if(reach>0){camera.updateMatrixWorld(true);const local=camera.worldToLocal(contact.clone());hand.grip(squeeze*.82);const basis=new T.Matrix4().makeBasis(new T.Vector3(0,-1,0),new T.Vector3(0,0,1),new T.Vector3(-1,0,0)),worldQ=new T.Quaternion().setFromRotationMatrix(basis);hand.g.quaternion.copy(camera.getWorldQuaternion(new T.Quaternion()).invert().multiply(worldQ));const offset=new T.Vector3(0,.12,-.035).multiplyScalar(.8).applyQuaternion(hand.g.quaternion);local.add(new T.Vector3(.044,0,0).applyQuaternion(camera.getWorldQuaternion(new T.Quaternion()).invert()));hand.g.position.copy(new T.Vector3(.22,-.45,-.6)).lerp(local.sub(offset),reach);}else hand.reset();state=time<1?'approaching':time<1.5?'offering':time<2.8?'shaking':time<3.2?'releasing':'returning';document.getElementById('intro-task').textContent=time<1.5?'ניגש לרובוט ומושיט יד':'ברוך הבא למעבדה • לחיצת יד';document.getElementById('intro-prompt').textContent=(matchMedia('(pointer:coarse)').matches?'פעולה':'E')+' • להמשיך';if(time>=4.6)finish();return true;}

 armPose(0);return{begin,update,get completed(){return state==='done';},get robot(){return robot;},get target(){return{x:start.x,z:start.z+1.25,title:'גש לרובוט ולחץ E ללחיצת יד'};},skip(){stopSpeech();finish();},dispose(){finish();hand.g.removeFromParent();},get active(){return state!=='waiting'&&state!=='done';},get state(){return state;},get palm(){return palm;},get playerHand(){return hand.g;},get contact(){return contact.clone();}};
}
